from rdkit import Chem
from rdkit.Chem import rdMolTransforms as T
import pandas as pd
df=pd.read_csv('/app/data/TB3_Conf_Properties.csv')
patt=Chem.MolFromSmarts('[S;R]-[c,C;R](-[NX3;H1,H0])')
res=[]
for i in range(1,13):
    m=Chem.MolFromMolFile(f'conf{i}.mol',removeHs=False,sanitize=False)
    m.UpdatePropertyCache(strict=False)
    # find S, C bonded to S and to N(amine)
    for a in m.GetAtoms():
        if a.GetSymbol()=='S':
            for c in a.GetNeighbors():
                for n in c.GetNeighbors():
                    if n.GetSymbol()=='N' and n.GetDegree()==3 and not any(x.GetSymbol()=='O' for x in n.GetNeighbors()):
                        for c2 in n.GetNeighbors():
                            if c2.GetSymbol()=='C' and c2.GetIdx()!=c.GetIdx():
                                d=T.GetDihedralDeg(m.GetConformer(),a.GetIdx(),c.GetIdx(),n.GetIdx(),c2.GetIdx())
                                res.append((i,d,df.iloc[i-1,1],df.iloc[i-1,2]))
for r in res: print(r)
EOF
python3 /tmp/dih.py

